describe('Mark Record as Favourite', () => {
  beforeEach(() => {
    cy.visit('/records');
  });

  it('should successfully mark a record as favourite', () => {
    // Intercept the API call to mark as favourite
    cy.intercept('POST', '/api/records/*/mark-as-favourite').as('markAsFavourite');

    // Find and click the favourite button on a record
    cy.get('[data-testid="record-item-1"]').within(() => {
      cy.get('[data-testid="favourite-button"]').click();
    });

    // Wait for the API call
    cy.wait('@markAsFavourite');

    // Verify success message appears
    cy.get('[data-testid="success-toast"]').should('be.visible').should('contain', 'Record marked as favourite');

    // Verify favourite button state changes
    cy.get('[data-testid="record-item-1"]').within(() => {
      cy.get('[data-testid="favourite-button"]').should('have.class', 'is-active');
      cy.get('[data-testid="favourite-icon"]').should('have.attr', 'aria-label', 'Remove from favourites');
    });

    // Verify favourite count updates
    cy.get('[data-testid="favourite-count"]').should('contain', '1');
  });

  it('should handle API errors when marking a record as favourite', () => {
    // Intercept the API call and mock an error response
    cy.intercept('POST', '/api/records/*/mark-as-favourite', {
      statusCode: 500,
      body: { error: 'Internal server error' }
    }).as('markAsFavouriteError');

    // Find and click the favourite button on a record
    cy.get('[data-testid="record-item-2"]').within(() => {
      cy.get('[data-testid="favourite-button"]').click();
    });

    // Wait for the failed API call
    cy.wait('@markAsFavouriteError');

    // Verify error message is displayed
    cy.get('[data-testid="error-toast"]').should('be.visible').should('contain', 'Failed to mark as favourite');

    // Verify favourite button state does not change
    cy.get('[data-testid="record-item-2"]').within(() => {
      cy.get('[data-testid="favourite-button"]').should('not.have.class', 'is-active');
      cy.get('[data-testid="favourite-icon"]').should('have.attr', 'aria-label', 'Add to favourites');
    });

    // Verify favourite count remains unchanged
    cy.get('[data-testid="favourite-count"]').should('contain', '0');
  });
});
